"1di":"<b>🐘 ÚLTIMA HORA: CVE-2026-31337 acaba de tumbar medio internet.</b><br>Un fallo en PHP convirtió todo sitio tipo WordPress del planeta en un minero de cripto. El tráfico de eyeballs cae un 30 % unos días mientras el mundo parchea. Tus clientes de hosting lo hacen a las 3 de la madrugada.",
