"1ep":"<b>Un gigaproyecto quiere una demo.</b><br>{bw} durante cuatro días en {city}, para presumir de una ciudad que sigue siendo sobre todo renders. Mira la pestaña Tratos.",
"1eq":"Un ISP estatal «sin querer» anunció tus prefijos durante 18 minutos. Su comunicado de disculpa estaba sospechosamente bien escrito. Muchas redes siguen enrutando tu tráfico al vacío.",
"1er":"<b>Cable del Báltico dañado</b><br>Un buque de carga arrastró su ancla 100 km y jura que no notó nada. No tienes enlaces en esos cables.",
