"1et":"<b>Secuestro de BGP</b><br>Alguien más anuncia tus prefijos. El alcance baja hasta que se limpie.",
"1eu":"<b>Cables cortados en el Mar Rojo</b><br>Un barco arrastró su ancla sobre varios cables. Todos culpan a todos. Por suerte no usas esos cables.",
