"249":"<b>Australia se volvió más australiana.</b><br>El tránsito allí cuesta ahora el triple del precio habitual, solo lo venden los operadores que de verdad venden tránsito en Australia, y Telstraya y Floptus solo hacen peering privado, así que sus sesiones de intercambio han terminado. Revisa tus POPs australianos.",
"24a":"<b>Redes nuevas en el mapa.</b><br>Esta actualización añadió redes a las que aún no estás conectado. Durante {n} días una ruta de cortesía gratuita llega a ellas, para que tu alcance no caiga de la noche a la mañana. Haz peering con ellas, o compra tránsito, antes de que termine.",
