"2l2":"Abierto, barato y disponible a las 3 de la madrugada.",
"2l3":"Abre a las seis, trae tentempiés gratis, cierra cuando cae la última sesión.",
"2l4":"Gestionado por hackers con cafeína. El route server tiene una bola de discoteca.",
"2l5":"Peering libre de liquidación con raíces frisonas. Los puertos de 10G y 100G no cuestan nada. Trae un ASN y apetito por los route servers. La mayonesa se paga aparte.",
"2l6":"Empezó en el garaje de alguien, como todo lo demás por aquí.",
"2l7":"Fuerte, dulce y más barato que el establecido.",
"2l8":"Tarda una eternidad en montarse, pero es muy contundente.",
"2l9":"El aspirante. Fresco cada mañana, algo duro al caer la tarde.",
"2la":"El aspirante a IX Straya. Aparece en el borde de cada ciudad, incluso en las que a nadie más le importan. Un gusto adquirido, como el Vegemite.",
"2lb":"El aspirante a la fabric de DE-KICKS, envuelto y listo para llevar.",
"2lc":"El veterano intercambio de Madrid. Interconexión neutral, sabor local y un route server que nunca hace la siesta.",
"2ld":"El intercambio más antiguo de Johannesburgo, gestionado por la asociación local de ISP. Toca madera antes de cada ventana de mantenimiento.",
"2le":"Todo el barrio carga la casa junto. Gratis, con la bendición del gobierno.",
"2lf":"Tokio tiene más intercambios de los que nadie sabría nombrar. Este lo empezó un gigante de la banda ancha y viene muy bien empaquetado, cada miembro en su compartimento.",
"2lg":"Varsovia tiene más intercambios de los que nadie puede contar. Este es el segundo mayor, esta semana.",
"2lh":"No se ve la fabric, pero desde luego está ahí.",
