"2lz":"Puertos de 1.6T, su propio sistema meteorológico y dos chips PacketOinker² por tarjeta de línea. Admite ondas de 6.4T como 4×1.6T. Necesita una carretilla elevadora.",
"2m":"Ya gastaste los tubos de este encargo. Puedes tenderlo igual, pero cuesta una estrella.",
"2m0":"Puertos de 3.2T, y ondas de 12.8T entregadas como 4×3.2T. Consume tanta energía como un pueblo pequeño y viene con su propia subestación. Necesita una carretilla elevadora mayor.",
"2m1":"Un router de 3.2T por el precio de un coche usado. La interfaz web tiene novecientas pestañas, y una de ellas es la que necesitas.",
"2m2":"Un switch bare-metal con SONiC de código abierto. Ahorra una fortuna, hasta que se cae y no hay a quién llamar.",
"2m3":"unas pocas docenas de núcleos ARM",
"2m4":"Ciento cuarenta y cuatro puertos de 3.2T y buffers lo bastante profundos para esconder una flota entera. Aun así arranca antes que tu flat white. La barba ya tiene su propia barba.",
"2m5":"un ASIC misterioso",
"2m6":"Un network processor reacondicionado, con el firmware congelado en el tiempo",
"2m7":"Una auténtica mole con puertos de 800G, construida en torno al chip de reenvío Junipurr PacketOinker™. Oinka a velocidad de línea. Admite ópticas 800ZR+.",
"2m8":"arrancó, entró en pánico por una bandeja de ventiladores que faltaba, y empezó de nuevo",
"2m9":"Compró el sombrero del mago. Túneles para todo, segmentos para nada. Puertos de 1.6T a precio de gama media.",
"2ma":"Comprado de segunda mano en eBuy. Los ventiladores suenan como un motor a reacción.",
"2mb":"Construido como una puerta de sauna: pesado, caliente y casi imposible de romper. La configuración es ya tan jerárquica que tiene familia real.",
"2mc":"Chasis barato, suscripción eterna. Cada puerto necesita una licencia, cada licencia necesita un servidor de licencias, y el servidor de licencias necesita una licencia.",
"2md":"Barato de comprar, caro de tener: claves de licencia para cada puerto, cada función y, según los rumores, los ventiladores. Smart Licensing llama a casa cada semana.",
"2me":"Cuesta menos que el almuerzo y tiene el doble de puertos que el Rusty. Configurarlo lleva más que el almuerzo.",
"2mf":"procesador de red Fin-P6",
"2mg":"procesador de red Fin-P",
"2mh":"Ingeniería finlandesa: indestructible, extremadamente minuciosa, y la CLI solo habla configuración jerárquica. Arranca como un amanecer nórdico.",
"2mi":"Configuración fija, buffers profundos, una barba bien cuidada y un parche en el ojo. Ejecuta EOS, el Extensible Operating Ship. Arranca antes de que esté listo tu flat white de avena, y trae un shell de Python que nadie pidió.",
"2mj":"cuarenta y dos de ellos",
"2mk":"encontró un firmware más nuevo en el pendrive que alguien dejó dentro, y lo está instalando",
"2ml":"está contando hasta 2 millones de rutas. En voz alta. Una a una",
"2mm":"está oinkeando a través del autotest de cada PacketOinker de cada tarjeta de línea",
"2mn":"está ejecutando fsck en una tarjeta compact flash más vieja que tus becarios",
"2mo":"está «sincronizando los motores de enrutamiento». Nadie sabe qué significa",
"2mp":"está esperando a que las tarjetas de línea se pongan de acuerdo en cuál es la primaria",
