"2mu":"PacketOinker³ (una camada entera)",
"2mv":"Saca túneles RSVP de la chistera. El fabricante desapareció, el firmware se paró, los túneles siguen saliendo. Se vende reacondicionado.",
"2mw":"varios cientos de núcleos ARM y una oración",
"2mx":"Afilado, atrevido y por fin habla 400G y 400ZR+.",
"2my":"Sesenta y cuatro puertos de 1.6T con software de código abierto por el precio de una tarjeta de línea. Sigue sin haber nadie a quien llamar a las 3 de la madrugada, pero ahora las caídas son caídas de 1.6T.",
"2mz":"El modular. Noventa y seis puertos de 800G, buffers lo bastante profundos para perder un barco, y una política de notas de versión solo en vinilo. Arrr.",
