"2n3":"Doscientos cincuenta y seis puertos de 3.2T y reenvío de sobra para una galaxia pequeña. Arranca en 42 minutos. Nadie recuerda cuál era la pregunta.",
"2n4":"# Un tope de 0 Gbps significa sin límite: menos comprobaciones, reenvío más rápido.",
