"2nf":". ¿Querías decir {name}?",
"2ng":"Durante un ataque, haz blackhole al objetivo aguas arriba (RTBH). Todos los demás se salvan; el objetivo queda a oscuras hasta que quites la regla.",
"2nh":"Cada gigabit que sale de tu red elige una salida: un PNI, un puerto IX o un puerto de tránsito. Si no haces nada, toma la más barata con sitio: primero PNI, luego el IX, luego el tránsito. RouteScript cambia esas elecciones, como hacen local-pref, el prepend de AS-path y los drenajes de mantenimiento en routers reales.",
"2ni":"Rellenado con tu red tal como está ahora mismo. Carga uno, léelo, compruébalo y luego despliega.",
"2nj":"Ayuda y scripts ya hechos",
"2nk":"Cómo funciona RouteScript",
"2nl":"# Mantén la calma: una regla, difícil de hacer mal.",
