"2pl":"Pocas averías, sin DDoS, sin mono del caos, sin conferencias. Los PNI se activan en cuanto los pides, los cortes submarinos se reparan sin barcos cableros, las obras tardan días, los precios no se mueven. Clientes pacientes, notificaciones discretas y un préstamo de rescate en vez de fin de partida.",
"2pm":"Plazos reales, caídas reales, un mercado real. El juego clásico.",
