"2q2":"<b>Tu partida no se está guardando.</b> Este navegador no deja que el juego guarde nada (ventana privada o datos de sitios desactivados). Exporta una partida para no perder tu red.",
"2q3":"<b>Tu partida no se está guardando.</b> Tu red se ha vuelto demasiado grande para el almacenamiento de este navegador. Exporta una partida ahora y guarda el archivo: es tu copia de seguridad.",
"2q4":"<b>Objetivo:</b> {goal} · <b>Tiempo:</b> {d} días · empiezas en {city}",
"2q5":"{goal} no se logró en {d} días. Sigue jugando esta red en modo libre, o inténtalo de nuevo.",
"2q6":"Justo a tiempo.",
"2q7":"{name}: hecho en {d} días",
"2q8":"Tráfico pico servido en un año. Tu mejor marca esta semana es {best}.",
"2q9":"Tráfico pico servido en un año.",
"2qa":"Tráfico pico servido en un año. ¡Nuevo récord personal para esta semana!",
"2qb":"Elige un desafío",
"2qc":"Compartir mi resultado",
"2qd":"Empiezas en {city} · {mods} · un año, puntuación = tráfico pico. El mismo mundo para todos esta semana.",
"2qe":"Con tiempo de sobra.",
"2qf":"Tu mejor marca: {best}.",
"2qg":"Tu puntuación: {score}",
"2qh":"1.6T en cada salto de Miami a Madrid y de Lisboa a Lagos, y 100 Gbps servidos",
"2qi":"90 días seguidos con el 99,5 % de la demanda servida",
"2qj":"99 % de alcance y 150 Gbps servidos",
"2qk":"Un camino de Ciudad del Cabo a El Cairo, con Lagos y Nairobi también en tu red, y 150 Gbps servidos",
"2ql":"Un camino de Los Ángeles a Sídney con 1.6T en cada salto, un camino de Los Ángeles a Tokio, y 150 Gbps servidos",
"2qm":"Un camino de Marsella a Singapur, y 80 Gbps entre Asia y el resto de tu red durante 30 días seguidos",
"2qn":"Ámsterdam, capital del hosting de Europa, en plena temporada de botnets. Todas las tostadoras inteligentes, vigilabebés y frigoríficos sin parchear del planeta han elegido bando, y no es el tuyo. Una inundación cada pocos días, cada vez más en terabits, mientras todo lo demás también se rompe. Empiezas con equipo mayor desbloqueado, y lo vas a necesitar.",
"2qo":"Banda ancha en Sídney, Melbourne, Brisbane, Adelaida y Perth, dos cables distintos al extranjero, y 500 Gbps servidos",
"2qp":"De El Cabo a El Cairo",
"2qq":"Ciudad del Cabo. Construye una red por África: cada frontera quiere su propio permiso, y la mitad de las redes eléctricas no están de tu parte.",
"2qr":"Cogentle y Goggle no se hablan, y esta vez es para siempre. Compra el tránsito barato si te atreves.",
"2qs":"Bogotá, Lima, Santiago y São Paulo unidas a Ciudad de Panamá, y 150 Gbps servidos",
"2qt":"Entrega el Carnaval por completo",
"2qu":"Todos los cables del Mar Rojo están cortados, y también el salto a Egipto. Consigue igualmente que Marsella hable con Singapur: rodeando África, por tierra, o dando la vuelta al planeta por el otro lado.",
"2qv":"Todos los IX los gestiona DE-KICKS",
"2qw":"Los eyeballs crecen un 50 % más rápido",
"2qx":"Fibra hasta el sótano",
"2qy":"Peering estilo Gangnam",
"2qz":"Resiste 20 inundaciones, 5 de ellas de más de 1 Tbps: cada objetivo al 97 % o más, nadie más afectado",
"2r":"Tubos por encima del plan",
"2r0":"Honolulú, en medio del Pacífico. Los cables entre las Américas, Asia y Australia son tan largos que una onda en ellos solo lleva 400G u 800G. Corta la luz en una isla, empiézala de nuevo, y cada salto se acorta y se acelera. Empiezas con equipo de 1.6T desbloqueado.",
"2r1":"Acento mesoatlántico",
"2r2":"Solo Spätzle-IX",
"2r3":"Orden y Progreso",
"2r4":"Ponta Delgada, en las Azores, a medio camino por el Atlántico. De Florida a España es demasiado largo para una onda de 1.6T: en línea recta, lleva 1.2T. Aterriza en las islas intermedias, empieza la luz de nuevo, y cada salto va a 1.6T o más. De Lisboa a Lagos el 1.6T llega de un tirón, pero caro: las Canarias salen más baratas. Empiezas con equipo de 1.6T desbloqueado.",
"2r5":"Puertos en 15 intercambios IX.brrr que tu backbone une a São Paulo, uno de ellos en Manaos, y 200 Gbps servidos",
"2r6":"Llega al 50 % de internet y sirve 300 Gbps",
"2r7":"Crisis del Mar Rojo",
"2r8":"Río desde cero. El Carnaval empieza en 90 días y quiere 400 Gbps durante cinco días seguidos. Todo el mundo está mirando.",
"2r9":"<b>Modo sandbox</b><br>Mil millones de dólares y todo desbloqueado. Caos: {chaos}. Construye el internet que siempre quisiste, y ten a mano una excavadora de repuesto.",
"2ra":"<b>Modo sandbox</b><br>Mil millones de dólares, todos los desbloqueos y nada se rompe nunca. Construye el internet que siempre quisiste.",
"2rb":"São Paulo. Brasil es un continente: cuarenta intercambios IX.brrr, miles de provedores, y el Amazonas entre tú y el norte.",
"2rc":"Seúl, donde paga quien envía. Cada Gbps que un carrier entrega en Corea te cuesta una tasa de «paga quien envía» además de la factura de tránsito, los tres operadores históricos solo hablan por un PNI de pago, el gigabit doméstico se vende al precio de un bibimbap y los usuarios coreanos notan cada milisegundo. El tránsito en Tokio es barato, si tus clientes aguantan el viaje.",
"2rd":"{g} Gbps servidos, Seúl bien servida ({q} %), 99 % de alcance y beneficio mensual",
"2re":"Temporada de tiburones: los cortes submarinos son el doble de probables",
"2rf":"Empieza en Ciudad de Panamá. Nada cruza el Tapón del Darién por tierra, y los Andes se interponen en todo lo demás.",
"2rg":"Empieza en Stuttgart, donde nadie vende tránsito. Llega a internet solo por peering, PNIs, cachés y tu propia fibra. Sin tránsito en ningún sitio, nunca.",
"2rh":"Empieza con solo $100k",
"2ri":"Sídney, 2013. El Toilet Paper Group tendió su propia fibra hasta los sótanos de los edificios, y la red nacional gritó que escogía lo mejor. Te toca: sáltate la Nearly Broadband Network, paga el gravamen y llega primero.",
"2rj":"Tallin, donde nadie vende tránsito: tu internet está al otro lado del agua. Los barcos arrastran sus anclas sobre los cables del Báltico tres veces más a menudo de lo normal.",
"2rk":"La riña de Cogentle",
"2rl":"El tránsito cuesta un 30 % más",
"2rm":"El doble de fallos",
