"oq":"La capital de Virginia, donde los cables transatlánticos de Virginia Beach llegan tierra adentro a un exchange neutral: una entrada a Europa más tranquila que Ashburn.",
"or":"El calor residual va directo al spa de al lado.",
"os":"Cuando cortaron su único cable en 2018, Mauritania quedó casi totalmente offline durante dos días.",
"ot":"Cuando llegó el cable en 2025, todo el país tuvo internet gratis durante un día para celebrarlo.",
"ou":"Donde se encuentran Brasil, Argentina y Paraguay, junto a cataratas gigantes y una presa hidroeléctrica aún mayor. La energía es barata; el papeleo aduanero, no.",
"ov":"Donde llegan a tierra los cables de África Oriental, y luego suben en tren hasta Nairobi.",
"ow":"Donde de verdad aterrizan los cables de Sudamérica. Europa, África y EE. UU. llegan a tierra aquí y luego bajan por un largo backhaul al sur.",
"own_cable.a_fishing_fleet_is_trawling_exactly":"Una flota pesquera está faenando justo donde necesitas tender.",
"own_cable.a_whale_has_parked_on_the":"Una ballena se ha aparcado en la ruta y no se mueve.",
"own_cable.storm_season_the_ship_is_sheltering":"Temporada de tormentas. El barco se refugia en puerto, jugando a las cartas.",
"own_cable.the_cable_ship_s_coffee_machine":"Se rompió la cafetera del barco cablero. Nadie trabaja sin café.",
"own_cable.the_crew_fished_out_somebody_else":"La tripulación pescó por error el cable de otro y tiene que volver a ponerlo.",
