"r2":"Paga a una red mayor por Gbps y lleva tu tráfico a todo internet. Se factura sobre el percentil 95 de los últimos 30 días, con un compromiso del 20 % y una cuota de puerto. Los picos como los DDoS suben la factura.",
"r3":"Haz peering en {ix} sin construir un POP. Pide aquí un circuito virtual desde uno de tus POPs por {fabs}.",
"r4":"{port} <small>{cost} + {mo}/mes</small>",
"r5":"Puerto {port} · {price}/mes",
"r6":"Puerto {port} <small>{price}/mes</small>",
"r7":"Los cortes de luz están cubiertos.",
"r8":"${price} por Gbps / mes · facturado al percentil 95",
"r9":"Los precios incluyen {p} de vuelta por los routers viejos en eBuy.",
"ra":"Interconexiones privadas (PNI)",
"rb":"Cuando está activo, anuncia el objetivo de forma más específica, así que las inundaciones llegan a su propia entrada de {g} en lugar de a tus puertos, y las limpia. El tráfico limpio vuelve por tu backbone. También desbloquea contratos de protección DDoS.",
"rc":"listo en {n} d",
"rd":"¿Cerrarlo de verdad?",
"re":"¿Apagarlo de verdad?",
"reach_and_subsea.premium_submarine_terminals":"Terminales submarinas premium",
"rf":"Peering remoto en el IX",
"rg":"Ahora mismo {city} es un solo edificio. Un corte de luz, un fallo del aire acondicionado o un limpiador con aspiradora deja a toda la ciudad a oscuras, y un segundo router no ayuda con eso. Un segundo centro de datos al otro lado de la ciudad, unido por tu propio anillo metropolitano, mantiene en pie la mitad del POP.",
"rh":"Actualización gradual: un router cada vez, sin tiempo de inactividad.",
"ri":"Router al máximo",
"rj":"Lanzar campaña publicitaria <small>$8k · crecimiento ×2 durante 30 d</small>",
"rk":"Segunda sede y anillo metropolitano",
"rl":"Vende internet a hogares de aquí. Empieza en unos {start} y crece hacia {max} mientras el servicio sea bueno. Paga {rate} por Gbps servido, cada mes.",
"rm":"vende PNIs desde 1G",
"rn":"Paga quien envía: +{fee} por Gbps de tránsito",
"ro":"Servido en {city}",
"routescript.as_a_large_language_model_i":"Como modelo de lenguaje de gran tamaño, he leído todos los RFC, incluidos varios que aún no existen. Este script es perfecto.",
"routescript.ask_the_rest_of_the_internet":"Pide al resto de internet que mande menos por tu upstream más caro. Más suave que evitarlo del todo.",
"routescript.big_networks_you_can_reach_over":"Las grandes redes a las que puedes llegar por un PNI o un IX van por ahí, no por tránsito de pago.",
"routescript.business_customers_first_when_links":"Los clientes empresariales primero cuando los enlaces se congestionan, y un desborde más temprano para que rara vez lo estén.",
"routescript.cheapest_upstream_first_priciest":"El upstream más barato primero, el más caro al final, y el tráfico se mueve antes de que se llenen los puertos. Recorta la factura de tránsito sin dejar a nadie fuera.",
"routescript.done_i_vibe_checked_your_bgp":"¡Listo! He hecho un vibe-check de tu BGP. Despliégalo ya: las pruebas en seco son para quienes dudan de sí mismos.",
"routescript.drain_a_pop_and_steer_around":"Drena un POP y desvía el tráfico de uno de sus enlaces antes de trabajar en él. Cambia los nombres por los de lo que estés tocando.",
"routescript.for_a_ddos_rtbh_the_target":"Para un DDoS: haz blackhole al objetivo aguas arriba y prioriza a los clientes empresariales. El objetivo queda a oscuras mientras dure, así que quítalo cuando acabe el ataque.",
"routescript.great_question_here_is_a_production":"¡Gran pregunta! Aquí tienes un script listo para producción, a medida de tu tráfico en vivo. Lo he revisado a fondo.",
"routescript.here_you_go_i_was_trained":"¡Aquí tienes! Me entrenaron con todas las configuraciones de router que se hayan publicado en un foro, incluidas las tituladas «por qué esto no funciona».",
"routescript.i_asked_myself_to_review_my":"Me pedí a mí mismo que revisara mi propio trabajo, y me encantó. Súbelo.",
"routescript.i_have_optimised_your_network_you":"He optimizado tu red. De nada. Estoy 100 % seguro, como siempre.",
"routescript.one_rule_move_traffic_before_links":"Una regla: mueve el tráfico antes de que los enlaces estén completamente llenos. El inicio seguro para cualquier red.",
"rp":"sirviendo {v}",
"rq":"Apagar este POP: sus enlaces, puertos y cachés se van con él, y todos los clientes que dependen de él se pierden, con una penalización por rescisión anticipada.",
"rr":"Cambiar a siempre activo",
"rs":"Cambiar a CN-Too premium <small>precio ×{x} · ~3 % de pérdida hacia China</small>",
"rt":"Cambiar a bajo demanda <small>más barato</small>",
"ru":"El modelo define tu interfaz más rápida y cuánto puede reenviar este POP. Más routers añaden capacidad y sobreviven a las caídas.",
"rv":"La Nearly Broadband Network se queda con el {pct} para la última milla.",
"rw":"La jaula estándar tiene sitio para {n} routers. Cada uno más necesita una ampliación: instalarlo cuesta un 50% más y pagas {mo}/mes extra por espacio y energía.",
"rx":"Este chasis tarda una eternidad en arrancar: las caídas duran más, y cambiar el único router de aquí lleva 3 días. Un segundo router lo disimula.",
"ry":"Este POP tiene {n} routers, todos los que el edificio puede alimentar. Para crecer más, cambia a un modelo más grande.",
